const out=[];
for (const el of document.querySelectorAll('a,button,div,span')) {
  const cs=getComputedStyle(el);
  const txt=(el.textContent||'').trim();
  if (cs.cursor==='pointer' && txt && txt.length<60) {
    const r=el.getBoundingClientRect();
    if (r.width>10 && r.height>5)
      out.push({t:txt.slice(0,45), tag:el.tagName, cls:(el.className||'').slice(0,30), x:Math.round(r.x+r.width/2), y:Math.round(r.y+r.height/2)});
  }
}
return JSON.stringify(out.slice(0,15));

const out=[];
for (const el of document.querySelectorAll('*')) {
  const txt=(el.textContent||'').trim();
  if (/18 or older|Enter Game/i.test(txt) && txt.length<50 && el.children.length<=1) {
    const r=el.getBoundingClientRect();
    out.push({t:txt.slice(0,45), tag:el.tagName, cls:(el.className||'').slice(0,40), x:Math.round(r.x+r.width/2), y:Math.round(r.y+r.height/2), w:Math.round(r.width)});
  }
}
return JSON.stringify(out.slice(0,8));

